<?php
namespace App\Extensions\ChatbotWhatsapp\System\Providers;
use App\Extensions\ChatbotWhatsapp\System\Contracts\MessagingProviderInterface;
abstract class AbstractHttpMessagingProvider implements MessagingProviderInterface { public function __construct(protected array $config=[]){} public function capabilities():array{return ['whatsapp','sms','mms','media','unicode','templates','delivery_reports','scheduled_sending'];} public function verifyWebhook(array $headers,string $body):bool{return true;} public function normalizeInbound(array $payload):array{return ['provider'=>$this->key(),'channel'=>$payload['channel']??'sms','from'=>$payload['from']??null,'to'=>$payload['to']??null,'text'=>$payload['text']??null,'media'=>$payload['media']??[],'raw'=>$payload];} public function schedule(array $message,\DateTimeInterface $sendAt):array{$message['scheduled_at']=$sendAt->format(DATE_ATOM);return $this->send($message);} public function deliveryReport(array $payload):array{return ['id'=>$payload['id']??null,'status'=>$payload['status']??'unknown','raw'=>$payload];} protected function fallback(array $message):array{return ['id'=>null,'status'=>'queued','provider'=>$this->key(),'message'=>$message];} }
